#pragma once
// C++17 工程片段：保存“速度 + 采样时刻”的一致快照，不依赖 ROS。
// 输入：速度 m/s、同一单调时钟下的时间 s；输出：是否接收、可选的新鲜快照。
#include <cmath>
#include <mutex>
#include <optional>
#include <stdexcept>

struct VelocitySample {
  double velocity_m_s;
  double stamp_s;
};

class VelocityCache {
public:
  explicit VelocityCache(double max_age_s) : max_age_s_(max_age_s) {
    if (!std::isfinite(max_age_s) || max_age_s < 0.0) {
      throw std::invalid_argument("最大年龄必须为有限非负秒数");
    }
  }
  bool put(double velocity_m_s, double stamp_s, double now_s) {
    // 先检查字段与时间方向；本类不负责校准两个时钟的偏移。
    if (!std::isfinite(velocity_m_s) || !std::isfinite(stamp_s) ||
        !std::isfinite(now_s) || stamp_s < 0.0 || stamp_s > now_s ||
        now_s-stamp_s > max_age_s_) {return false;}
    std::lock_guard<std::mutex> guard(mutex_);
    if (sample_ && stamp_s < sample_->stamp_s) {return false;}
    sample_ = VelocitySample{velocity_m_s, stamp_s};
    return true;
  }
  std::optional<VelocitySample> read(double now_s) const {
    std::lock_guard<std::mutex> guard(mutex_);
    if (!std::isfinite(now_s) || !sample_ || now_s < sample_->stamp_s ||
        now_s-sample_->stamp_s > max_age_s_) {return std::nullopt;}
    return sample_;  // 复制值快照后释放锁；调用者不持有指向内部可变对象的引用。
  }
private:
  const double max_age_s_;
  mutable std::mutex mutex_;
  std::optional<VelocitySample> sample_;
};
// 有锁实现提供字段一致性；不承诺无阻塞，也不构成硬实时截止期证明。

def planning_lab():
    """在四邻接、单位正代价、点机器人模型中比较 A* 与 Dijkstra。"""
    import heapq

    width, height, resolution_m = 7, 5, 0.1
    start, goal = (0,0), (6,0)
    walls = {(3,y) for y in range(4)}  # 顶部 y=4 留一个通道。

    def search(obstacles, use_heuristic):
        # g 的单位是格数；启发式是到目标的曼哈顿格数，与四邻接模型一致。
        def heuristic(p):
            return abs(p[0]-goal[0])+abs(p[1]-goal[1]) if use_heuristic else 0
        if start in obstacles or goal in obstacles:
            return None
        heap = [(heuristic(start),0,start)]
        distance, previous = {start:0}, {}
        while heap:
            _, g, current = heapq.heappop(heap)
            if g != distance.get(current):
                continue  # 跳过已被更短路径取代的旧队列项。
            if current == goal:
                path = [goal]
                while path[-1] != start:
                    path.append(previous[path[-1]])
                return list(reversed(path))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nxt = current[0]+dx, current[1]+dy
                if not (0 <= nxt[0] < width and 0 <= nxt[1] < height):
                    continue
                if nxt in obstacles:
                    continue
                new_g = g+1
                if new_g < distance.get(nxt,float("inf")):
                    distance[nxt], previous[nxt] = new_g,current
                    heapq.heappush(heap,(new_g+heuristic(nxt),new_g,nxt))
        return None  # 队列耗尽是明确的无路结果，不能继续执行旧路径。

    path_a = search(walls,True)
    path_d = search(walls,False)
    assert path_a is not None and path_d is not None
    assert len(path_a)-1 == len(path_d)-1 == 14
    assert all(p not in walls for p in path_a)
    assert all(abs(a[0]-b[0])+abs(a[1]-b[1]) == 1 for a,b in zip(path_a,path_a[1:]))
    assert search(walls | {(3,4)},True) is None
    result = {"最优步数": len(path_a)-1, "路径长度_m": (len(path_a)-1)*resolution_m,
              "封闭通道结果": "无路"}
    print("网格搜索", result)
    return result

if __name__ == "__main__":
    planning_lab()

// plan_ready.cpp：依赖已运行的 Panda MoveIt 教学演示，只规划，不执行。
// 输入：当前 /joint_states、机器人模型以及 SRDF 中 panda_arm/ready 定义。
// 输出：规划成功/失败和轨迹点数。关节角单位 rad；两个缩放参数无量纲。
#include <exception>
#include <stdexcept>
#include <memory>
#include <thread>
#include <rclcpp/rclcpp.hpp>
#include <moveit/move_group_interface/move_group_interface.hpp>

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  auto node = std::make_shared<rclcpp::Node>(
    "plan_ready", rclcpp::NodeOptions().automatically_declare_parameters_from_overrides(true));
  rclcpp::executors::SingleThreadedExecutor executor;
  executor.add_node(node);
  // MoveGroupInterface 的等待需要 ROS 回调推进，所以在独立线程 spin。
  // 先确保 move_group 与关节状态已通过本章检查；此例没有完整生产超时封装。
  std::thread spinner([&executor]() {executor.spin();});
  int status = 0;
  try {
    moveit::planning_interface::MoveGroupInterface group(node, "panda_arm");
    group.setPlanningTime(5.0);               // 秒：单次规划预算，不是执行时限。
    group.setMaxVelocityScalingFactor(0.1);   // 关节最大速度的比例，范围 0~1。
    group.setMaxAccelerationScalingFactor(0.1); // 最大加速度比例，同样无量纲。
    group.setStartStateToCurrentState();      // 先取最新状态，避免复用旧起点。
    if (!group.setNamedTarget("ready")) {
      throw std::runtime_error("SRDF 中缺少 ready 命名目标");
    }
    moveit::planning_interface::MoveGroupInterface::Plan plan;
    const auto result = group.plan(plan);    // 请求规划；没有 group.move()/execute()。
    if (result == moveit::core::MoveItErrorCode::SUCCESS) {
      RCLCPP_INFO(node->get_logger(), "仅规划成功：%zu 个关节轨迹点",
        plan.trajectory_.joint_trajectory.points.size());
    } else {
      RCLCPP_ERROR(node->get_logger(), "规划失败，错误码 %d", result.val);
      status = 1;
    }
  } catch (const std::exception & error) {
    RCLCPP_ERROR(node->get_logger(), "项目错误：%s", error.what());
    status = 1;
  }
  // 按依赖顺序停止回调、等待线程退出，再关闭 ROS；线程不越过节点寿命。
  executor.cancel();
  spinner.join();
  rclcpp::shutdown();
  return status;
}
